Lemma tl_geo :
  (* [comment removed for export] *)
  SB + c * 2 ^ 32 <= AB /\ AB + S <= SB + c * 2 ^ 32 + 0xE0000000 /\ AB mod 16 = 0
  /\ l_PRB L <= SB /\ SB + 2 ^ 37 + 4096 <= l_PRB L + 0x2000011000 /\ l_PRB L + 0x2000011000 <= l_ACEIL L
  /\ K_HIGH_SHADOW_hi <= l_PRB L
  (* [comment removed for export] *)
