  /\ (DNB + 0x100000 <= K_LOW_SHADOW_lo \/ K_HIGH_SHADOW_hi <= DNB) /\ (SSB + 0x800000 <= K_LOW_SHADOW_lo \/ K_HIGH_SHADOW_hi <= SSB).
