  depot_rep (fst (depot_put D tr)) BK DNB SSB m4 ->
  pc_cells m4 (pc_addr T c) (Z.of_nat (length (ca Σ c)) - 1) (MaxCount c) (ClassSize c) ->
  evt asegs tail_post (MS (mkR (Z_to_bv 64 0xa1660) (Z_to_bv 64 (B + -144)) gp (Z_to_bv 64 tpA) t0 t1 t2 (Z_to_bv 64 1) (Z_to_bv 64 n)
